const sd = $getWorkflowStaticData('global');
const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;

// Prune covered topics older than 7 days, keep max 50 (migrates old string format too)
sd.usedTopics = (sd.usedTopics || [])
  .map(t => typeof t === 'string' ? { title: t, ts: now } : t)
  .filter(t => t && t.title && (now - (t.ts || 0)) < SEVEN_DAYS)
  .slice(-50);

// Keep the last 100 rejected article links
sd.rejectedLinks = (sd.rejectedLinks || []).slice(-100);

// Reset per-run state
sd.attemptCount = 0;
sd.candidates = [];
sd.currentSelection = null;
delete sd.runCount;

return $input.all();

const sd = $getWorkflowStaticData('global');
const now = Date.now();

const rejected = new Set(sd.rejectedLinks || []);
const usedTitles = new Set((sd.usedTopics || []).map(t => String(t.title).toLowerCase().trim()));

const all = $input.all()
  .map(i => i.json)
  .filter(a => a && a.title && a.link && a.isoDate);

function collect(hours) {
  const cutoff = now - hours * 60 * 60 * 1000;
  const seenTitles = new Set();
  const seenLinks = new Set();
  const out = [];
  for (const a of all) {
    const ts = new Date(a.isoDate).getTime();
    if (isNaN(ts) || ts < cutoff) continue;
    const titleKey = String(a.title).toLowerCase().trim();
    if (seenTitles.has(titleKey) || seenLinks.has(a.link)) continue;
    seenTitles.add(titleKey);
    seenLinks.add(a.link);
    if (rejected.has(a.link)) continue;
    if (usedTitles.has(titleKey)) continue;
    out.push({
      title: String(a.title).trim(),
      link: a.link,
      snippet: String(a.contentSnippet || '').slice(0, 300),
      isoDate: a.isoDate,
    });
  }
  return out;
}

// Try the last 4 hours first; if nothing is left, extend to 6 hours
let windowHours = 4;
let candidates = collect(4);
if (candidates.length === 0) {
  windowHours = 6;
  candidates = collect(6);
}

if (candidates.length === 0) {
  return [{ json: {
    found: false,
    reason: 'No publishable articles were found. I checked the last 4 hours, then extended the window to 6 hours, but the feeds came back empty (or only contained articles that were already covered or previously rejected).',
  } }];
}

sd.candidates = candidates;
return [{ json: {
  found: true,
  windowHours: windowHours,
  candidateCount: candidates.length,
  candidates: candidates,
  usedTopics: (sd.usedTopics || []).map(t => t.title),
} }];

