parameters.jsCode:
const sd = $getWorkflowStaticData('global');

let sel = sd.currentSelection || {};
if (!sel.link) {
  try { sel = $('Select Article').first().json || {}; } catch (e) {}
}

const out = ($input.first().json.output) || {};
const post = String(out.post || '').trim();
const headline = String(out.headline || sel.title || '').trim();
const imageQuery = String(out.imageQuery || '').trim();

if (!post) {
  throw new Error('News Reporter returned an empty post.');
}

let attempt = sd.attemptCount || 0;
if (attempt === 0) {
  try { attempt = $('Select Article').first().json.attempt || 1; } catch (e) { attempt = 1; }
}

return [{ json: {
  headline: headline,
  post: post,
  title: sel.title || '',
  link: sel.link || '',
  attempt: attempt,
  imageQuery: imageQuery,
} }];

const src = $input.first().json || {};
const fp = $('Format Post').first().json || {};

let results = [];
if (Array.isArray(src.results)) results = src.results;

let hasImage = false;
let imageUrl = '';
let photographer = '';
let photographerUrl = '';
let downloadLocation = '';
let creditLine = '';

if (results.length > 0) {
  const p = results[0] || {};
  const urls = p.urls || {};
  imageUrl = urls.regular || urls.full || urls.small || '';
  const user = p.user || {};
  photographer = user.name || 'Unsplash';
  photographerUrl = (user.links && user.links.html) || 'https://unsplash.com';
  downloadLocation = (p.links && p.links.download_location) || '';
  if (imageUrl) {
    hasImage = true;
    creditLine = 'Photo by ' + photographer + ' on Unsplash';
  }
}

let post = String(fp.post || '');
if (hasImage && creditLine) {
  post = post + '\n\n' + creditLine;
}

return [{ json: {
  headline: fp.headline || '',
  post: post,
  title: fp.title || '',
  link: fp.link || '',
  attempt: fp.attempt || 1,
  imageQuery: fp.imageQuery || '',
  hasImage: hasImage,
  imageUrl: imageUrl,
  photographer: photographer,
  photographerUrl: photographerUrl,
  downloadLocation: downloadLocation,
} }];

